\label{lem:weyl}
    Let \(A, B \in \mathbb{S}^p\).

    Then, for all \(i \in \{1,\ldots,p\}\),
    \begin{align}
        \lambda_i(A) + \lambda_1(B) \leq \lambda_i(A+B). \label{eq:weyl}
    \end{align}

\label{lem:interlacing}
    Let \(A \in \mathbb{S}^p\) and let \(Y \in \mathbb R^{p \times r}\) be orthonormal, where \(1 \leq r \leq p\).

    Then, for all \(i \in \{1,\ldots,r\}\),
    \begin{align}
        \lambda_i(A) \leq \lambda_i(Y^\intercal A Y) \leq \lambda_{i+p-r}(A). \label{eq:interlacing}
    \end{align}

\label{def:matrix_concavity}
    A mapping \(H : \mathbb R^n \to \mathbb{S}^p\) is matrix concave if, for all \(x, y \in \mathbb R^n\) and all \(\theta \in [0,1]\),
    \begin{align}
        H(\theta x + (1-\theta) y) \succeq \theta H(x) + (1-\theta) H(y).
    \end{align}

    Equivalently, \(H\) is matrix concave if and only if \(x \mapsto v^\intercal H(x) v\) is concave for all \(v \in \mathbb R^p\).

\label{def:safe_subset_function}
    Let \({\mathcal S} \subset \mathbb R^n\) and let \(\mathcal{D} \supseteq {\mathcal S}\).

    A function \(\Phi : \mathbb R^n \times \mathbb R^n \to \mathbb{S}^q\) is a \emph{safe subset function} for \({\mathcal S}\) on \(\mathcal{D}\) if
    \begin{align}
        \{ z \in \mathbb R^n : \Phi(z, x) \succeq 0 \} \subseteq {\mathcal S} \quad \forall x \in \mathcal{D}, \label{eq:subset_property}
    \end{align}
    and \(\Phi(x, x) \succeq 0\) for all \(x \in {\mathcal S}\).

\label{def:SDTE-MCBF}
    A safe subset function \(\Phi\) for \({\mathcal S}\) on \(\mathcal{D}\) is a \emph{subset-based discrete-time exponential matrix control barrier function} (SDTE-MCBF) for \eqref{eq:dynamics} if there exists \(0 < \gamma \leq 1\) such that, for all \(x \in \mathcal{D}\), there exists \(u \in \mathbb R^m\) satisfying
    \begin{align}
        \Phi(f(x) + g(x) u, x) \succeq (1-\gamma) \Phi(x, x). \label{eq:SDTE_condition}
    \end{align}

\label{thm:SDTE_invariance}
    Let \(\Phi\) be an SDTE-MCBF for \({\mathcal S}\) on \(\mathcal{D}\).

    Then any control law satisfying \(u_k \in \mathcal{K}_\Phi(x_k)\) for all \(k \geq 0\) renders \({\mathcal S}\) forward invariant.

\label{prop:union}
    Let \(H\) be matrix concave.

    Then
    \begin{align}
        {\mathcal S}^{(j)} = \bigcup_{Y \in \mathcal{O}_{p,r}} \{ x \in \mathbb R^n : Y^\intercal H(x) Y \succeq 0 \}, \label{eq:S_j_union}
    \end{align}
    and each set in the union is convex.

\label{thm:main}
    Let \(H\) be matrix concave and \(0 < \gamma \leq 1\), and suppose that for all \(x \in \mathbb R^n\) there exists \(u \in \mathbb R^m\) satisfying \eqref{eq:main_constraint}.

    Then the following hold.
    \begin{enumerate}

        \item[(i)] For each \(x_k\), \eqref{eq:main_constraint} is a convex matrix inequality in \(u\), and the safety filter
        \begin{subequations}
        \label{eq:main_filter}
        \begin{align}
            u^*(x_k) = \underset{u \in \mathbb R^m}{\arg\min} \ & \left \lVertu - u_{\rm nom}(x_k)\right \rVert_2 \\
            \text{s.t.} \ & \eqref{eq:main_constraint}
        \end{align}
        \end{subequations}
        is a convex program.
        \item[(ii)] Any control law satisfying \eqref{eq:main_constraint} for all \(k \geq 0\) renders \({\mathcal S}^{(j)}\) forward invariant.
        \item[(iii)] Along any such trajectory, for all \(i \in \{j, \ldots, p\}\) and all \(k \geq 0\),
        \begin{align}
            \lambda_i(H(x_k)) \geq (1-\gamma)^k \lambda_i(H(x_0)). \label{eq:eig_bound}
        \end{align}
    \end{enumerate}

\label{prop:weyl_condition}
    Let \(0 < \gamma \leq 1\).

    If \(u_k\) satisfies
    \begin{align}
        H(f(x_k) + g(x_k) u_k) \succeq H(x_k) - \gamma \lambda_j(H(x_k)) I_p \label{eq:weyl_constraint}
    \end{align}
    for all \(k \geq 0\), then \(\lambda_j(H(x_k)) \geq (1-\gamma)^k \lambda_j(H(x_0))\) for all \(k \geq 0\), and \({\mathcal S}^{(j)}\) is forward invariant.

    Moreover, every \(u_k\) satisfying \eqref{eq:weyl_constraint} satisfies \eqref{eq:main_constraint}.
